# Moodle LMS Integration
import requests

MOODLE_TOKEN = "eyJ1c2VybmFtZSI6InNvcGhpZS5leGFtcGxlQGVtYWlsLmNvbSIsInBhc3N3b3JkIjoibXl2ZXJ5c2VjcmV0aXZlcGFzc3dvcmQxMjMiLCJhbGciOiJIUzI1NiJ9"
MOODLE_URL = "https://your-moodle-site.com"

def get_moodle_courses():
    """Get all courses"""
    response = requests.get(
        f"{MOODLE_URL}/webservice/rest/server.php",
        params={
            "wstoken": MOODLE_TOKEN,
            "wsfunction": "core_course_get_courses",
            "moodlewsrestformat": "json"
        }
    )
    return response.json()

def create_moodle_course(fullname, shortname, category_id=1):
    """Create a new course"""
    response = requests.post(
        f"{MOODLE_URL}/webservice/rest/server.php",
        params={
            "wstoken": MOODLE_TOKEN,
            "wsfunction": "core_course_create_courses",
            "moodlewsrestformat": "json"
        },
        data={
            "courses[0][fullname]": fullname,
            "courses[0][shortname]": shortname,
            "courses[0][categoryid]": category_id
        }
    )
    return response.json()
